<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDown, ArrowUp, ArrowUpDown, Search, X } from '@lucide/vue'
import type { SpotlightIndicator } from './spotlight.api'
import SpotlightChart from './SpotlightChart.vue'

const props = defineProps<{ indicators: SpotlightIndicator[] }>()
type MacroItem = { name: string; category: string; frame: string; kind: 'macrobar' | 'macroline'; min: number; max: number; decimals: number; unit: string; values: number[]; dates: string[] }
const items = computed<MacroItem[]>(() => props.indicators.filter(indicator => indicator.history.length).map(indicator => {
  const values = indicator.history.map(point => point.value)
  return {
    name: indicator.name,
    category: indicator.table === 'SURVEYS' ? 'Sentiment' : 'Conditions',
    frame: '—',
    kind: indicator.chart_type === 'column' ? 'macrobar' : 'macroline',
    min: Math.min(indicator.chart_type === 'column' ? 0 : Infinity, ...values),
    max: Math.max(indicator.chart_type === 'column' ? 0 : -Infinity, ...values),
    decimals: Math.abs(values.at(-1) ?? 0) < 10 ? 2 : 1,
    unit: '',
    values,
    dates: indicator.history.map(point => point.date),
  }
}))
const tab = ref<'overview' | 'indicators' | 'research'>('overview')
const period = ref<'1M' | '3M' | '6M'>('3M')
function windowStart(item: MacroItem) {
  const end = new Date(`${item.dates.at(-1)}T12:00:00Z`)
  end.setUTCMonth(end.getUTCMonth() - ({ '1M': 1, '3M': 3, '6M': 6 })[period.value])
  return end.toISOString().slice(0, 10)
}
function chartDates(item: MacroItem) { return item.dates.filter(date => date >= windowStart(item)) }
function chartValues(item: MacroItem) { return item.values.slice(-chartDates(item).length) }
function chartCount(item: MacroItem) { return chartDates(item).length }
const query = ref('')
const category = ref('All')
const categories = computed(() => ['All', ...new Set(items.value.map(item => item.category))])
const filtered = computed(() => items.value.filter((item) => (category.value === 'All' || item.category === category.value) && `${item.name} ${item.category} ${item.frame}`.toLowerCase().includes(query.value.trim().toLowerCase())))
type SortKey = 'name' | 'frame' | 'current' | 'change'
const sortKey = ref<SortKey>('name')
const sortDirection = ref<'asc' | 'desc'>('asc')
const sorted = computed(() => filtered.value.slice().sort((left, right) => {
  let result: number
  if (sortKey.value === 'name') result = left.name.localeCompare(right.name)
  else if (sortKey.value === 'frame') result = left.frame.localeCompare(right.frame)
  else if (sortKey.value === 'current') result = current(left) - current(right)
  else result = change(left) - change(right)
  return sortDirection.value === 'asc' ? result : -result
}))
function sortBy(key: SortKey) { if (sortKey.value === key) sortDirection.value = sortDirection.value === 'asc' ? 'desc' : 'asc'; else { sortKey.value = key; sortDirection.value = 'asc' } }
const expanded = ref<MacroItem | null>(null)
const note = ref<number | null>(null)
const research = computed(() => [
  { title: 'Fund flows in context', item: items.value.find(item => item.name === 'Mutual Fund Flow (with ETFs)') ?? items.value[0], offset: 0 },
  { title: 'Available cash and market conditions', item: items.value.find(item => item.name === 'NYSE Available Cash') ?? items.value[0], offset: 5 },
  { title: 'Consumer confidence over time', item: items.value.find(item => item.name === 'U of Mich. Consumer Confidence') ?? items.value[0], offset: 12 },
])
const number = (value: number, decimals: number) => value.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })
const current = (item: MacroItem, offset = 0) => item.values[item.values.length - 1 - offset]
const change = (item: MacroItem) => current(item) - item.values[item.values.length - 2]
const signed = (value: number, decimals: number) => `${value > 0 ? '+' : ''}${number(value, decimals)}`
function status(item: MacroItem, offset = 0) { return item.kind === 'macrobar' ? current(item, offset) < 0 ? 'Below zero' : 'Above zero' : 'Current reading' }
function statusClass(_item: MacroItem, _offset = 0) { return 'bg-[var(--app-surface-muted)] text-[var(--app-text-muted)]' }
const sampleDate = (item: MacroItem, offset = 0) => item.dates[item.dates.length - 1 - offset]
function reset() { query.value = ''; category.value = 'All' }
</script>

<template>
  <section class="space-y-4" data-testid="macro-content">
    <div class="flex gap-6 overflow-x-auto border-b border-[var(--app-border)]" role="tablist" aria-label="Macro views"><button v-for="view in [{key:'overview',label:'Overview',count:''},{key:'indicators',label:'Indicators',count:String(items.length)},{key:'research',label:'Research',count:'3'}] as const" :key="view.key" type="button" role="tab" :aria-selected="tab === view.key" class="whitespace-nowrap border-b-2 px-1 py-3 text-xs font-semibold" :class="tab === view.key ? 'border-[var(--app-primary)] text-[var(--app-primary)]' : 'border-transparent text-[var(--app-text-muted)]'" @click="tab = view.key">{{ view.label }} <span v-if="view.count" class="ml-1 text-[10px]">{{ view.count }}</span></button></div>
    <template v-if="tab === 'overview'"><header class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="font-semibold">Chart summary <span class="text-xs font-normal text-[var(--app-text-muted)]">{{ Math.min(items.length, 6) }} indicators</span></h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Current readings and recent history for the selected indicators.</p></div><div class="flex items-center gap-2 text-xs"><span class="text-[var(--app-text-muted)]">Chart window</span><div class="inline-flex rounded-md border border-[var(--app-border)] bg-[var(--app-surface-soft)] p-0.5" role="group" aria-label="Chart window"><button v-for="option in ['1M','3M','6M'] as const" :key="option" type="button" class="rounded px-3 py-1.5 text-xs font-semibold" :class="period === option ? 'bg-[var(--app-surface)] text-[var(--app-primary)] shadow-sm' : 'text-[var(--app-text-muted)]'" :aria-pressed="period === option" @click="period = option">{{ option }}</button></div></div></header><div class="grid gap-4 lg:grid-cols-2 2xl:grid-cols-3"><article v-for="item in items.slice(0,6)" :key="item.name" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex items-start justify-between gap-3 px-4 pt-4"><div><span class="text-[10px] uppercase tracking-wide text-[var(--app-text-muted)]">{{ item.kind === 'macrobar' ? 'Economic indicator' : 'Market indicator' }}</span><h3 class="mt-1 text-sm font-semibold">{{ item.name }}</h3></div><button type="button" :aria-label="`Expand ${item.name}`" class="h-7 w-7 rounded border border-[var(--app-border)] text-[var(--app-text-muted)] hover:text-[var(--app-primary)]" @click="expanded = item">↗</button></header><div class="flex flex-wrap items-start justify-between gap-2 px-4 pt-3"><div><strong class="text-2xl tabular-nums">{{ number(current(item), item.decimals) }}</strong><small v-if="item.unit" class="ml-1 text-[10px] text-[var(--app-text-muted)]">{{ item.unit }}</small><p class="mt-1 text-[11px] text-[var(--app-text-muted)]"><b class="text-[var(--app-primary)]">{{ signed(change(item), item.decimals) }}</b> vs previous session</p></div><span class="rounded px-2 py-1 text-[10px] font-semibold" :class="statusClass(item)">{{ status(item) }}</span></div><div class="pl-2 pt-2"><SpotlightChart :name="item.name" :values="chartValues(item)" :dates="chartDates(item)" :period="chartCount(item)" :min="item.min" :max="item.max" :decimals="item.decimals" :kind="item.kind" /></div><div class="flex gap-3 px-4 py-2 text-[10px] text-[var(--app-text-muted)]"><span>{{ item.kind === 'macrobar' ? 'Economic indicator · zero baseline' : 'Market indicator' }}</span></div><footer class="flex justify-between border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-4 py-2 text-[10px] text-[var(--app-text-muted)]"><span>{{ period }} range <b>{{ number(Math.min(...chartValues(item)), item.decimals) }} – {{ number(Math.max(...chartValues(item)), item.decimals) }}</b></span><span>{{ chartCount(item) }} samples</span></footer></article></div><p class="text-xs text-[var(--app-text-muted)]">Demo data · Sample readings and histories for design review.</p></template>
    <section v-else-if="tab === 'indicators'" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="flex items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">Indicators</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Current values, changes from the previous session and reading context</p></div><span class="rounded bg-[var(--app-primary-soft)] px-2 py-1 text-[10px] text-[var(--app-primary)]">Demo data</span></header><div class="flex flex-wrap gap-2 border-b border-[var(--app-border)] p-4"><label class="flex min-w-[210px] max-w-md flex-1 items-center gap-2 rounded border border-[var(--app-border)] px-3"><Search :size="15" class="text-[var(--app-text-muted)]" /><input v-model="query" type="search" aria-label="Search indicators" placeholder="Search indicators…" class="h-9 min-w-0 flex-1 bg-transparent text-xs outline-none" /></label><select v-model="category" aria-label="Indicator category" class="h-9 rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-3 text-xs"><option v-for="option in categories" :key="option">{{ option }}</option></select><button type="button" class="rounded border border-[var(--app-border)] bg-[var(--app-primary-soft)] px-3 text-xs font-semibold text-[var(--app-primary)]" @click="reset">Reset</button></div><div class="overflow-x-auto"><table class="w-full min-w-[900px] border-collapse text-left text-[.8125rem]"><thead class="bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr class="border-b border-[var(--app-border)]"><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('name')">Indicator<ArrowUp v-if="sortKey === 'name' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'name'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('frame')">Horizon<ArrowUp v-if="sortKey === 'frame' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'frame'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('current')">Current<ArrowUp v-if="sortKey === 'current' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'current'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('change')">Change<ArrowUp v-if="sortKey === 'change' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'change'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3">As of</th><th class="px-4 py-3">Context</th><th class="w-12 px-4 py-3"></th></tr></thead><tbody><tr v-for="(item, rowIndex) in sorted" :key="item.name" class="border-b border-[var(--app-border-muted)] last:border-0 hover:bg-[var(--app-surface-hover)]" :class="rowIndex % 2 ? 'bg-[var(--app-row-even)]' : ''"><td class="px-4 py-3"><button type="button" class="font-semibold text-[var(--app-text-secondary)] hover:text-[var(--app-primary)]" @click="expanded = item">{{ item.name }}</button><small class="block text-[var(--app-text-muted)]">{{ item.category }}</small></td><td class="px-4 py-3 text-[var(--app-text-muted)]">{{ item.frame }}</td><td class="px-4 py-3 font-semibold tabular-nums">{{ number(current(item), item.decimals) }} <small>{{ item.unit }}</small></td><td class="px-4 py-3 tabular-nums" :class="change(item) > 0 ? 'text-[var(--app-positive)]' : change(item) < 0 ? 'text-[var(--app-negative)]' : 'text-[var(--app-text-muted)]'">{{ signed(change(item), item.decimals) }}</td><td class="px-4 py-3 text-[var(--app-text-muted)]">{{ sampleDate(item) }}</td><td class="px-4 py-3"><span class="rounded-full px-2.5 py-1 text-[10px] font-semibold" :class="statusClass(item)">{{ status(item) }}</span></td><td class="px-4 py-3 text-right"><button type="button" :aria-label="`Expand ${item.name}`" class="h-6 w-6 rounded border border-[var(--app-border)] bg-[var(--app-surface)] text-sm leading-5 text-[var(--app-text-muted)] hover:bg-[var(--app-primary-soft)] hover:text-[var(--app-primary)]" @click="expanded = item">↗</button></td></tr><tr v-if="!sorted.length"><td colspan="7" class="p-8 text-center text-[var(--app-text-muted)]">No indicators match your search. Try another term or reset the filters.</td></tr></tbody></table></div><footer class="flex justify-between border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]"><span>{{ filtered.length }} of {{ items.length }} indicators</span><span>Change vs previous session · pp = percentage points</span></footer></section>
    <section v-else class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><header class="flex justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">Research notes</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Related research and the indicator readings discussed in each note</p></div><span class="h-fit rounded bg-[var(--app-primary-soft)] px-2 py-1 text-[10px] text-[var(--app-primary)]">Demo research</span></header><div class="overflow-x-auto"><table class="w-full min-w-[720px] border-collapse text-left text-[.8125rem]"><thead class="bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr class="border-b border-[var(--app-border)]"><th v-for="heading in ['Published','Research','Related indicator','Reading','Context','']" :key="heading" class="px-4 py-3">{{ heading }}</th></tr></thead><tbody><tr v-for="(entry,index) in research" :key="entry.title" class="border-b border-[var(--app-border-muted)] last:border-0 hover:bg-[var(--app-surface-hover)]" :class="index % 2 ? 'bg-[var(--app-row-even)]' : ''"><td class="px-4 py-3 text-[var(--app-text-muted)]">{{ sampleDate(entry.item, entry.offset) }}</td><td class="px-4 py-3"><button type="button" class="font-semibold text-[var(--app-primary)]" @click="note = index">{{ entry.title }}</button></td><td class="px-4 py-3">{{ entry.item.name }}</td><td class="px-4 py-3 font-semibold tabular-nums">{{ number(current(entry.item, entry.offset), entry.item.decimals) }}</td><td class="px-4 py-3"><span class="rounded-full px-2.5 py-1 text-[10px] font-bold" :class="statusClass(entry.item, entry.offset)">{{ status(entry.item, entry.offset) }}</span></td><td class="px-4 py-3 text-right"><button type="button" :aria-label="`Read example: ${entry.title}`" class="h-6 w-6 rounded border border-[var(--app-border)] bg-[var(--app-surface)] text-sm leading-5 text-[var(--app-text-muted)] hover:bg-[var(--app-primary-soft)] hover:text-[var(--app-primary)]" @click="note = index">↗</button></td></tr></tbody></table></div><footer class="flex justify-between border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]"><span>3 example notes</span><span>Illustrative dates, titles and readings</span></footer></section>
    <Teleport to="body"><div v-if="expanded || note !== null" class="fixed inset-0 z-[80] grid place-items-center bg-[var(--app-overlay)] p-4" role="dialog" aria-modal="true" :aria-label="expanded?.name ?? (note !== null ? research[note].title : '')"><section class="w-full max-w-4xl rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5 shadow-2xl"><header class="mb-4 flex justify-between gap-3"><div><p class="text-[10px] uppercase tracking-wide text-[var(--app-text-muted)]">{{ note !== null ? 'Demo research' : 'Indicator detail' }}</p><h2 class="mt-1 text-lg font-semibold">{{ expanded?.name ?? (note !== null ? research[note].title : '') }}</h2></div><button type="button" aria-label="Close detail" @click="expanded = null; note = null"><X :size="18" /></button></header><template v-if="expanded"><p class="mb-3 text-xs text-[var(--app-text-muted)]">{{ number(current(expanded), expanded.decimals) }} {{ expanded.unit }} · {{ status(expanded) }}</p><SpotlightChart :name="expanded.name" :values="chartValues(expanded)" :dates="chartDates(expanded)" :period="chartCount(expanded)" :min="expanded.min" :max="expanded.max" :decimals="expanded.decimals" :kind="expanded.kind" :height="300" /></template><template v-else-if="note !== null"><p class="mb-4 text-sm leading-6 text-[var(--app-text-secondary)]">This example focuses on <strong>{{ research[note].item.name }}</strong>. The illustrated reading is <strong>{{ number(current(research[note].item, research[note].offset), research[note].item.decimals) }}</strong> as of {{ sampleDate(research[note].item, research[note].offset) }}.</p><SpotlightChart :name="research[note].item.name" :values="research[note].item.values.slice(0, 126 - research[note].offset)" :dates="research[note].item.dates.slice(0, 126 - research[note].offset)" :period="63" :min="research[note].item.min" :max="research[note].item.max" :decimals="research[note].item.decimals" :kind="research[note].item.kind" :height="245" /></template></section></div></Teleport>
  </section>
</template>

